// LocalStorage & Cloud synchronization
(function() {
  const FAQ_STORAGE_KEY = "kh_faq_data_v1";
  try {
    const rawFaq = localStorage.getItem(FAQ_STORAGE_KEY);
    if (rawFaq) {
      const parsed = JSON.parse(rawFaq);
      if (parsed && typeof parsed === "object") {
        window.FAQ_DATA = parsed;
      }
    }
  } catch(e) {}

  window.saveFaqData = function(data) {
    window.FAQ_DATA = data;
    try {
      localStorage.setItem(FAQ_STORAGE_KEY, JSON.stringify(data));
      window.dispatchEvent(new CustomEvent("kh_faq_updated", { detail: data }));
    } catch(e) {}
    const FIRESTORE_URL = "https://firestore.googleapis.com/v1/projects/korayhussein-proofing/databases/(default)/documents/client_shoots/faq_config?key=AIzaSyD0b76g_32uPjLpeezf3QSlTSbAEbSeXjs";
    fetch(FIRESTORE_URL, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        fields: {
          updatedAt: { integerValue: String(Date.now()) },
          faqJson: { stringValue: JSON.stringify(data) }
        }
      })
    }).catch(() => {});
  };

  window.syncFaqFromCloud = async function() {
    try {
      const FIRESTORE_URL = "https://firestore.googleapis.com/v1/projects/korayhussein-proofing/databases/(default)/documents/client_shoots/faq_config?key=AIzaSyD0b76g_32uPjLpeezf3QSlTSbAEbSeXjs";
      const res = await fetch(FIRESTORE_URL, { cache: "no-store" });
      if (!res.ok) return;
      const json = await res.json();
      if (json && json.fields && json.fields.faqJson) {
        const cloudData = JSON.parse(json.fields.faqJson.stringValue);
        if (cloudData) {
          window.FAQ_DATA = cloudData;
          localStorage.setItem(FAQ_STORAGE_KEY, JSON.stringify(cloudData));
          window.dispatchEvent(new CustomEvent("kh_faq_updated", { detail: cloudData }));
        }
      }
    } catch(e) {}
  };
  try { window.syncFaqFromCloud(); } catch(e) {}
})();
